100	    public OwnerRestControllerV1(ClinicService clinicService,
101	                                 OwnerMapper ownerMapper,
102	                                 PetMapper petMapper,
103	                                 VisitMapper visitMapper,
104	                                 OwnerFieldsValidator ownerFieldsValidator,
105	                                 PostcodeValidator postcodeValidator,
106	                                 TelephoneNormalizer telephoneNormalizer,
107	                                 EmailNormalizer emailNormalizer,
108	                                 AddressNormalizer addressNormalizer,
109	                                 IdentityDuplicateValidator identityDuplicateValidator,
110	                                 HouseholdAssigner householdAssigner,
111	                                 CityCapacityValidator cityCapacityValidator,
112	                                 DailyRegistrationLimitValidator dailyRegistrationLimitValidator,
113	                                 BusinessDayAdjuster businessDayAdjuster,
114	                                 OwnerAuditLogger ownerAuditLogger) {
115	        this.clinicService = clinicService;
116	        this.ownerMapper = ownerMapper;
117	        this.petMapper = petMapper;
118	        this.visitMapper = visitMapper;
119	        this.ownerFieldsValidator = ownerFieldsValidator;
120	        this.postcodeValidator = postcodeValidator;
121	        this.telephoneNormalizer = telephoneNormalizer;
122	        this.emailNormalizer = emailNormalizer;
123	        this.addressNormalizer = addressNormalizer;
124	        this.identityDuplicateValidator = identityDuplicateValidator;
125	        this.householdAssigner = householdAssigner;
126	        this.cityCapacityValidator = cityCapacityValidator;
127	        this.dailyRegistrationLimitValidator = dailyRegistrationLimitValidator;
128	        this.businessDayAdjuster = businessDayAdjuster;
129	        this.ownerAuditLogger = ownerAuditLogger;
130	    }
131	
132	    /**
133	     * Registers the {@link OwnerFieldsValidator} so incoming owner payloads are checked for
134	     * missing or blank mandatory fields as part of the standard {@code @Valid} pass.
135	     */
136	    @InitBinder("ownerFieldsDto")
137	    void initOwnerFieldsBinder(WebDataBinder binder) {
138	        binder.addValidators(ownerFieldsValidator, postcodeValidator);
139	    }
140	
141	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
142	    @Override
143	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
144	        Collection<Owner> owners;
145	        if (lastName != null) {
146	            owners = this.clinicService.findOwnerByLastName(lastName);
147	        } else {
148	            owners = this.clinicService.findAllOwners();
149	        }
150	        if (owners.isEmpty()) {
151	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
152	        }
153	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
169	        HttpHeaders headers = new HttpHeaders();
170	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
171	        owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
172	        LocalDate registrationDate = owner.getRegistrationDate() != null
173	            ? owner.getRegistrationDate() : LocalDate.now();
174	        owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(registrationDate));
175	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
176	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
177	        dailyRegistrationLimitValidator.validate(owner.getRegistrationDate());
178	        cityCapacityValidator.validate(owner);
179	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
180	            householdAssigner.assignSharedHousehold(owner);
181	        }
182	        identityDuplicateValidator.validate(owner);
183	        this.clinicService.saveOwner(owner);
184	        ownerAuditLogger.logCreated(owner);
185	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
186	        headers.setLocation(UriComponentsBuilder.newInstance()
187	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
188	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
194	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
195	        if (currentOwner == null) {
196	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
197	        }
198	        currentOwner.setAddress(ownerFieldsDto.getAddress());
199	        currentOwner.setCity(ownerFieldsDto.getCity());
200	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
201	        currentOwner.setLastName(ownerFieldsDto.getLastName());
202	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
203	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
204	        this.clinicService.saveOwner(currentOwner);
205	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
206	    }
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Transactional
210	    @Override
211	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
212	        Owner owner = this.clinicService.findOwnerById(ownerId);
213	        if (owner == null) {
214	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
215	        }
216	        this.clinicService.deleteOwner(owner);
217	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
218	    }
219	
220	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
221	    @Override
222	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
223	        Owner owner = this.clinicService.findOwnerById(ownerId);
224	        if (owner == null) {
225	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
226	        }
227	        HttpHeaders headers = new HttpHeaders();
228	        Pet pet = petMapper.toPet(petFieldsDto);
229	        owner.setId(ownerId);
230	        pet.setOwner(owner);
231	        pet.getType().setName(null);
232	        this.clinicService.savePet(pet);
233	        PetDto petDto = petMapper.toPetDto(pet);
234	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
235	            .buildAndExpand(pet.getId()).toUri());
236	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
237	    }
238	
239	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
240	    @Override
241	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
242	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
243	        if (currentOwner != null) {
244	            Pet currentPet = this.clinicService.findPetById(petId);
245	            if (currentPet != null) {
246	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
247	                currentPet.setName(petFieldsDto.getName());
248	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
249	                this.clinicService.savePet(currentPet);
250	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
251	            }
252	        }
253	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
254	    }
255	
256	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
257	    @Override
258	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
259	        HttpHeaders headers = new HttpHeaders();
260	        Visit visit = visitMapper.toVisit(visitFieldsDto);
261	        Pet pet = new Pet();
262	        pet.setId(petId);
263	        visit.setPet(pet);
264	        this.clinicService.saveVisit(visit);
265	        VisitDto visitDto = visitMapper.toVisitDto(visit);
266	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
267	            .buildAndExpand(visit.getId()).toUri());
268	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
269	    }
270	
271	
272	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
273	    @Override
274	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
275	        Owner owner = this.clinicService.findOwnerById(ownerId);
276	        if (owner != null) {
277	            Pet pet = owner.getPet(petId);
278	            if (pet != null) {
279	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
280	            }
281	        }
282	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
283	    }
284	}
