18	
19	import org.springframework.samples.petclinic.model.RegionPostcodes;
20	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
21	import org.springframework.stereotype.Component;
22	import org.springframework.validation.Errors;
23	import org.springframework.validation.Validator;
24	
25	/**
26	 * Enforces that a supplied owner postcode is valid for the city's region.
27	 * <p>
28	 * Validation runs only when a postcode is present and well-formed (4 digits); its
29	 * shape is enforced declaratively by the DTO's {@code @Pattern} constraint. Registered
30	 * on the owner request binder so an out-of-range postcode surfaces through the same
31	 * {@code BindingResult} as the other owner-field checks, yielding a 400 response.
32	 */
33	@Component
34	public class PostcodeValidator implements Validator {
35	
36	    @Override
37	    public boolean supports(Class<?> clazz) {
38	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
39	    }
40	
41	    @Override
42	    public void validate(Object target, Errors errors) {
43	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
44	        String postcode = owner.getPostcode();
45	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
46	            return;
47	        }
48	        if (!RegionPostcodes.isValidForCity(owner.getCity(), Integer.parseInt(postcode))) {
49	            errors.rejectValue("postcode", "postcode.outOfRange",
50	                "postcode is not valid for the city's region");
51	        }
52	    }
53	}
