24	/**
25	 * Rolls a date forward onto a business day: when the given date falls on a Saturday or
26	 * Sunday it is advanced to the following Monday, otherwise it is returned unchanged.
27	 */
28	@Component
29	public class BusinessDayAdjuster {
30	
31	    /**
32	     * Return {@code date} if it is a weekday, otherwise the next Monday.
33	     *
34	     * @param date the date to adjust
35	     * @return the same date when it is a business day, or the following Monday for a weekend date
36	     */
37	    public LocalDate toBusinessDay(LocalDate date) {
38	        LocalDate adjusted = date;
39	        while (adjusted.getDayOfWeek() == DayOfWeek.SATURDAY || adjusted.getDayOfWeek() == DayOfWeek.SUNDAY) {
40	            adjusted = adjusted.plusDays(1);
41	        }
42	        return adjusted;
43	    }
44	}
