23	/**
24	 * Guards owner creation against duplicate identities: telephone, email and household are
25	 * consolidated into a single {@link OwnerIdentity#key(Owner) identity key}, and a candidate is
26	 * rejected only when its whole key equals an existing owner's. Owners that differ in any
27	 * segment (for example two household members with different telephones) are distinct and both
28	 * allowed.
29	 */
30	@Component
31	public class IdentityDuplicateValidator {
32	
33	    private final ClinicService clinicService;
34	
35	    private final OwnerIdentity ownerIdentity;
36	
37	    public IdentityDuplicateValidator(ClinicService clinicService, OwnerIdentity ownerIdentity) {
38	        this.clinicService = clinicService;
39	        this.ownerIdentity = ownerIdentity;
40	    }
41	
42	    /**
43	     * Reject {@code candidate} when its identity key already belongs to another owner.
44	     *
45	     * @param candidate the owner about to be created, with its telephone, email and household
46	     * identifier already normalized
47	     * @throws DuplicateIdentityException if another owner shares the candidate's whole identity key
48	     */
49	    public void validate(Owner candidate) {
50	        String key = ownerIdentity.key(candidate);
51	        boolean taken = clinicService.findAllOwners().stream()
52	            .map(ownerIdentity::key)
53	            .anyMatch(key::equals);
54	        if (taken) {
55	            throw new DuplicateIdentityException(key);
56	        }
57	    }
58	}
