42	     * Assign {@code candidate} the household identifier it shares with any existing same-household
43	     * owners, back-filling that identifier onto members that do not yet carry it. A no-op when no
44	     * existing owner shares the candidate's household.
45	     *
46	     * @param candidate the owner about to be created; its {@code householdId} is set in place
47	     */
48	    public void assignSharedHousehold(Owner candidate) {
49	        List<Owner> members = households.findMembers(candidate);
50	        if (members.isEmpty()) {
51	            return;
52	        }
53	        String householdId = households.stableId(candidate);
54	        candidate.setHouseholdId(householdId);
55	        for (Owner member : members) {
56	            if (!householdId.equals(member.getHouseholdId())) {
57	                member.setHouseholdId(householdId);
58	                clinicService.saveOwner(member);
59	            }
60	        }
61	    }
62	}
