18	
19	import java.util.Comparator;
20	import java.util.List;
21	import java.util.Map;
22	
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Per-country length rules for the national portion of an E.164 number.
27	 * <p>
28	 * Each known country calling code fixes how many digits the national number must carry
29	 * (e.g. {@code +61} requires 9, {@code +1} requires 10). Given the digit string that
30	 * follows the {@code '+'}, this splits off the longest matching calling code and checks
31	 * the remaining national digits against that country's required length. A mismatch is
32	 * rejected with an {@link InvalidTelephoneException} (surfaced as {@code 400 Bad Request}).
33	 * Digit strings whose calling code is not recognised carry no per-country rule and pass.
34	 */
35	@Component
36	public class E164CountryRules {
37	
38	    /** Country calling code -> exact number of national digits it requires. */
39	    private static final Map<String, Integer> NATIONAL_LENGTHS = Map.of(
40	        "61", 9,
41	        "1", 10);
42	
43	    /** Calling codes tried longest-first so a longer code is preferred over a shorter prefix. */
44	    private static final List<String> CALLING_CODES = NATIONAL_LENGTHS.keySet().stream()
45	        .sorted(Comparator.comparingInt(String::length).reversed())
46	        .toList();
47	
48	    /**
49	     * Validate the national-number length of an E.164 digit string against its country.
50	     *
51	     * @param e164Digits the digits following the {@code '+'} (calling code plus national number)
52	     * @param rejectedValue the original client input, echoed in the rejection message
53	     * @throws InvalidTelephoneException if the national number is the wrong length for its country
54	     */
55	    public void validateNationalLength(String e164Digits, String rejectedValue) {
56	        for (String code : CALLING_CODES) {
57	            if (e164Digits.startsWith(code)) {
58	                int required = NATIONAL_LENGTHS.get(code);
59	                int actual = e164Digits.length() - code.length();
60	                if (actual != required) {
61	                    throw InvalidTelephoneException.wrongNationalLength(rejectedValue, code, required, actual);
62	                }
63	                return;
64	            }
65	        }
66	    }
67	}
