17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.util.List;
21	import java.util.Locale;
22	import java.util.UUID;
23	
24	import org.springframework.samples.petclinic.model.Owner;
25	import org.springframework.samples.petclinic.service.ClinicService;
26	import org.springframework.stereotype.Component;
27	
28	/**
29	 * Household identity for owners: two owners belong to the same household when their last name
30	 * and address match once compared case-insensitively and with runs of whitespace collapsed to
31	 * a single space. Provides the shared lookup and stable-identifier logic reused by the
32	 * duplicate guard and the shared-household assignment.
33	 */
34	@Component
35	public class Households {
36	
37	    private final ClinicService clinicService;
38	
39	    public Households(ClinicService clinicService) {
40	        this.clinicService = clinicService;
41	    }
42	
43	    /**
44	     * Existing owners that share {@code candidate}'s household (same normalized last name and
45	     * address). Intended for a not-yet-persisted candidate, so the candidate never appears in
46	     * the result.
47	     */
48	    public List<Owner> findMembers(Owner candidate) {
49	        String key = key(candidate);
50	        return clinicService.findOwnerByLastNameIgnoreCase(candidate.getLastName()).stream()
51	            .filter(existing -> key.equals(key(existing)))
52	            .toList();
53	    }
54	
55	    /**
56	     * The stable identifier every owner in {@code owner}'s household shares. Derived
57	     * deterministically from the household key, so the same household always yields the same id.
58	     */
59	    public String stableId(Owner owner) {
60	        return UUID.nameUUIDFromBytes(key(owner).getBytes(StandardCharsets.UTF_8)).toString();
61	    }
62	
63	    /**
64	     * Canonical household key: the normalized last name and address joined so that distinct
65	     * fields cannot collide.
66	     */
67	    private String key(Owner owner) {
68	        return normalize(owner.getLastName()) + "\n" + normalize(owner.getAddress());
69	    }
70	
71	    /**
72	     * Canonicalize a value for household comparison: {@code null} becomes empty, surrounding
73	     * whitespace is trimmed, internal whitespace runs collapse to a single space, and the result
74	     * is lower-cased.
75	     */
76	    private String normalize(String value) {
77	        if (value == null) {
78	            return "";
79	        }
80	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
81	    }
82	}
