45	/**
46	 * Global Exception handler for REST controllers.
47	 * <p>
48	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
49	 *
50	 * @author Vitaliy Fedoriv
51	 * @author Alexander Dudkin
52	 */
53	@ControllerAdvice
54	public class ExceptionControllerAdvice {
55	
56	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
57	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
58	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
59	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
60	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the same identity already exists";
61	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city already contains the maximum number of owners";
62	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners for today has already been reached";
63	
64	    /**
65	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
66	     * class.
67	     *
68	     * @param e     Object referring to the thrown exception.
69	     * @param status HTTP response status.
70	     * @param url URL request.
71	     */
72	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
73	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
74	        problemDetail.setType(URI.create(url.toString()));
75	        problemDetail.setTitle(e.getClass().getSimpleName());
76	        problemDetail.setDetail(detail);
77	        problemDetail.setProperty("timestamp", Instant.now());
78	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
79	        return problemDetail;
80	    }
81	
82	    /**
83	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
84	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
85	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
86	     * would catch it and report an authorization failure as a 500.
87	     *
88	     * @param e The {@link AccessDeniedException} to propagate
89	     * @throws AccessDeniedException always
90	     */
91	    @ExceptionHandler(AccessDeniedException.class)
92	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
93	        throw e;
94	    }
95	
96	    /**
97	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
98	     *
99	     * @param e The {@link Exception} to be handled
100	     * @param request {@link HttpServletRequest} object referring to the current request.
101	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
102	     */
103	    @ExceptionHandler(Exception.class)
104	    @ResponseBody
105	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
106	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
107	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
108	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
109	        return ResponseEntity.status(status).body(detail);
110	    }
111	
112	    /**
113	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
114	     * method returns a 404 Not Found status if an entity does not exist.
115	     *
116	     * @param e The {@link DataIntegrityViolationException} to be handled
117	     * @param request {@link HttpServletRequest} object referring to the current request.
118	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
119	     */
120	    @ExceptionHandler(DataIntegrityViolationException.class)
121	    @ResponseBody
122	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
123	        logger.warn("Data integrity violation at {} {}: {}",
124	            request.getMethod(),
125	            request.getRequestURI(),
126	            e.getMessage());
127	        logger.debug("Data integrity violation stacktrace", e);
128	        HttpStatus status = HttpStatus.NOT_FOUND;
129	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
130	        return ResponseEntity.status(status).body(detail);
131	    }
132	
133	    /**
134	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone does not
135	     * reduce to exactly ten digits after non-digit characters are stripped.
136	     *
137	     * @param e The {@link InvalidTelephoneException} to be handled
138	     * @param request {@link HttpServletRequest} object referring to the current request.
139	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
140	     */
141	    @ExceptionHandler(InvalidTelephoneException.class)
142	    @ResponseBody
143	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
144	        HttpStatus status = HttpStatus.BAD_REQUEST;
145	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
146	        return ResponseEntity.status(status).body(detail);
147	    }
148	
149	    /**
150	     * Handles {@link DuplicateIdentityException} raised when an owner is created whose whole
151	     * identity key (normalized telephone, email and household identifier) already belongs to
152	     * another owner.
153	     *
154	     * @param e The {@link DuplicateIdentityException} to be handled
155	     * @param request {@link HttpServletRequest} object referring to the current request.
156	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
157	     */
158	    @ExceptionHandler(DuplicateIdentityException.class)
159	    @ResponseBody
160	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
161	        HttpStatus status = HttpStatus.CONFLICT;
162	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
163	        return ResponseEntity.status(status).body(detail);
164	    }
165	
166	    /**
167	     * Handles {@link CityCapacityExceededException} raised when an owner is created in a city
168	     * that already contains the maximum number of owners.
169	     *
170	     * @param e The {@link CityCapacityExceededException} to be handled
171	     * @param request {@link HttpServletRequest} object referring to the current request.
172	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
173	     */
174	    @ExceptionHandler(CityCapacityExceededException.class)
175	    @ResponseBody
176	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
177	        HttpStatus status = HttpStatus.CONFLICT;
178	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
179	        return ResponseEntity.status(status).body(detail);
180	    }
181	
182	    /**
183	     * Handles {@link DailyRegistrationLimitExceededException} raised when an owner is created
184	     * after the maximum number of owners for the current day has already been registered.
185	     *
186	     * @param e The {@link DailyRegistrationLimitExceededException} to be handled
187	     * @param request {@link HttpServletRequest} object referring to the current request.
188	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
189	     */
190	    @ExceptionHandler(DailyRegistrationLimitExceededException.class)
191	    @ResponseBody
192	    public ResponseEntity<ProblemDetail> handleDailyRegistrationLimitExceededException(DailyRegistrationLimitExceededException e, HttpServletRequest request) {
193	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
194	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DAILY_LIMIT_REACHED);
195	        return ResponseEntity.status(status).body(detail);
196	    }
197	
198	    /**
199	     * Handles exception thrown by Bean Validation on controller methods parameters
200	     *
201	     * @param e The {@link MethodArgumentNotValidException} to be handled
202	     * @param request {@link HttpServletRequest} object referring to the current request.
203	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
204	     */
205	    @ExceptionHandler(MethodArgumentNotValidException.class)
206	    @ResponseBody
207	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
208	        HttpStatus status = HttpStatus.BAD_REQUEST;
209	        BindingErrorsResponse errors = new BindingErrorsResponse();
210	        BindingResult bindingResult = e.getBindingResult();
211	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
212	        if (bindingResult.hasErrors()) {
213	            errors.addAllErrors(bindingResult);
214	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
215	                .map(fieldError -> {
216	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
217	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
218	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
219	                        fieldError.getField(),
220	                        defaultMessage,
221	                        rejectedValue);
222	                    return new ValidationMessageDto(message)
223	                        .putAdditionalProperty("field", fieldError.getField())
224	                        .putAdditionalProperty("rejectedValue", rejectedValue)
225	                        .putAdditionalProperty("defaultMessage", defaultMessage);
226	                })
227	                .toList();
228	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
229	                .map(FieldError::getField)
230	                .distinct()
231	                .toList();
232	            logger.debug("Validation error at {} {}: {}",
233	                request.getMethod(),
234	                request.getRequestURI(),
235	                bindingResult.getFieldErrors());
236	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
237	            detail.setProperty("errors", invalidFields);
238	            return ResponseEntity.status(status).body(detail);
239	        }
240	        return ResponseEntity.status(status).body(detail);
241	    }
242	
243	}
