17	package org.springframework.samples.petclinic.service;
18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Decides whether an owner should carry a bulk-signup warning: the flag is raised once more
24	 * than {@value #BULK_SIGNUP_THRESHOLD} owners share the owner's registration date, signalling
25	 * an unusually high volume of same-day registrations. It reads the same per-day registration
26	 * count the daily-limit rule uses, only with a lower threshold.
27	 */
28	@Component
29	public class BulkSignupWarningEvaluator {
30	
31	    /** Number of same-day registrations above which the warning is raised. */
32	    static final int BULK_SIGNUP_THRESHOLD = 80;
33	
34	    private final ClinicService clinicService;
35	
36	    public BulkSignupWarningEvaluator(ClinicService clinicService) {
37	        this.clinicService = clinicService;
38	    }
39	
40	    /**
41	     * @param owner the owner whose registration date is checked
42	     * @return {@code true} when more than {@value #BULK_SIGNUP_THRESHOLD} owners are registered
43	     *         on the owner's registration date, {@code false} otherwise (including when the owner
44	     *         or its registration date is not yet known)
45	     */
46	    public boolean isWarranted(Owner owner) {
47	        if (owner == null || owner.getRegistrationDate() == null) {
48	            return false;
49	        }
50	        return clinicService.countOwnersRegisteredOn(owner.getRegistrationDate()) > BULK_SIGNUP_THRESHOLD;
51	    }
52	}
