17	
18	import java.util.Map;
19	
20	/**
21	 * Derives an owner's locality — the canonical region. The postcode range is preferred
22	 * (see {@link RegionPostcodes#regionForPostcode(String)}); only when the postcode is
23	 * absent or in no known range does a fixed city-to-region table decide. Owners that
24	 * resolve by neither route yield {@link #UNKNOWN}.
25	 */
26	public final class Locality {
27	
28	    /** Locality returned for any city not present in the table. */
29	    public static final String UNKNOWN = "UNKNOWN";
30	
31	    private static final Map<String, String> CITY_TO_REGION = Map.of(
32	        "Sydney", "NSW",
33	        "Melbourne", "VIC",
34	        "Brisbane", "QLD");
35	
36	    private Locality() {
37	    }
38	
39	    /**
40	     * Derives the region for an owner, preferring the postcode range and falling back to
41	     * the city-to-region table. Returns {@link #UNKNOWN} for a {@code null} owner or when
42	     * neither route resolves a region.
43	     */
44	    public static String forOwner(Owner owner) {
45	        if (owner == null) {
46	            return UNKNOWN;
47	        }
48	        String byPostcode = RegionPostcodes.regionForPostcode(owner.getPostcode());
49	        return byPostcode != null ? byPostcode : fromCity(owner.getCity());
50	    }
51	
52	    /**
53	     * Returns the canonical region for the given city, or {@link #UNKNOWN} when the
54	     * city is {@code null} or not present in the table.
55	     */
56	    public static String fromCity(String city) {
57	        if (city == null) {
58	            return UNKNOWN;
59	        }
60	        return CITY_TO_REGION.getOrDefault(city, UNKNOWN);
61	    }
62	}
